param([string]$ExcelPath=".\DETALLE PARA CONTEO PAREJAS.xlsx",[string]$OutputPath=".\asignaciones.json")
$ErrorActionPreference="Stop";$Salt="INV-GENERAL-2026-V1"
function Norm($v){if($null-eq$v){return""};return([string]$v).Trim().ToUpperInvariant()-replace'[^A-Z0-9]',''}
function Hash($t){$s=[Security.Cryptography.SHA256]::Create();try{return-join($s.ComputeHash([Text.Encoding]::UTF8.GetBytes($t))|%{$_.ToString('x2')})}finally{$s.Dispose()}}
$xl=New-Object -ComObject Excel.Application;$xl.Visible=$false;$xl.DisplayAlerts=$false
try{$wb=$xl.Workbooks.Open([IO.Path]::GetFullPath($ExcelPath),0,$true);$ws=$wb.Worksheets.Item('LISTADO');$tb=$ws.ListObjects.Item('DETALLE');$h=@{};for($c=1;$c-le$tb.ListColumns.Count;$c++){$h[[string]$tb.HeaderRowRange.Cells.Item(1,$c).Text]=$c};$best=@{};for($r=1;$r-le$tb.DataBodyRange.Rows.Count;$r++){$en=Norm $tb.DataBodyRange.Cells.Item($r,$h['E-NUMBER']).Value2;$p=([string]$tb.DataBodyRange.Cells.Item($r,$h['PRIORIDAD']).Text).Trim();$pn=999999;[void][int]::TryParse($p,[ref]$pn);$mesa=([string]$tb.DataBodyRange.Cells.Item($r,$h['MESA']).Text).Trim();if(!$en-or$en-eq'ENCRIPTADO'-or!$mesa-or$p-match'^[xX]$'){continue};$o=[pscustomobject]@{priority=$pn;id=(Hash "$Salt|$en");pareja=([string]$tb.DataBodyRange.Cells.Item($r,$h['PAREJA']).Text).Trim();mesa=$mesa;listado=([string]$tb.DataBodyRange.Cells.Item($r,$h['LISTADO']).Text).Trim();ubicacion=([string]$tb.DataBodyRange.Cells.Item($r,$h['UBICACION']).Text).Trim()};if(!$best.ContainsKey($en)-or$o.priority-lt$best[$en].priority){$best[$en]=$o}};$out=@($best.Values|Sort-Object id|Select id,pareja,mesa,listado,ubicacion);[IO.File]::WriteAllText([IO.Path]::GetFullPath($OutputPath),(ConvertTo-Json -InputObject $out -Depth 4),(New-Object Text.UTF8Encoding($false)));Write-Host "[OK] Asignaciones: $($out.Count)" -ForegroundColor Green}finally{if($wb){$wb.Close($false)};$xl.Quit()}